verus.description:
This challenge is an instance of Kaldewaij’s Search by Elimination [10], where an element with
a given property is located by eliminating elements that do not have that
property. The challenge was selected
as it involves a relatively simple but
interesting invariant, expressing that the maximal element is in the remaining
search space rather than maintaining the maximal element found so far.
public static int max(int[] a) {
int x = 0;
int y = a.length-1;
while (x != y) {
if (a[x] <= a[y]) x++;
else y--;
}
return x;
}

verus.solution:
use vstd::prelude::*;
fn main() {}
verus! {

#[allow(unused)]
pub fn max(a: &[i32]) -> (max_idx: usize)
    requires
        0 < a.len() <= usize::MAX,
    ensures
        forall|i: int| 0 <= i < a.len() ==> a[max_idx as int] >= a[i],
{
    let mut x = 0usize;
    let mut y = a.len() - 1;

    while x != y
        invariant
            forall|i: int|
                0 <= i < a.len() && a[i] > a[x as int] && a[i] > a[y as int] ==> x < i < y,
            0 <= x <= y < a.len(),
        decreases y - x,
    {
        if a[x] <= a[y] {
            x += 1;
        } else {
            y -= 1;
        }
    }  // x == y

    x
}

} // verus!

