why3.description:
Consider a binary tree:
class Tree {
Tree left, right, parent;
bool mark;
}
We are given a binary tree with the following properties:
● It is well formed, in the sense that following a child pointer (left or right) and then
following a parent pointer brings us to the original node. Moreover, the parent
pointer of the root is null.
● It has at least one node, and each node has 0 or 2 children.
We do not know the initial value of the mark fields.
Our goal is to set all mark fields to true. The algorithm below (Morris 1979) works in time linear
in the number of nodes, as usual, but uses only a constant amount of extra space.
void markTree(Tree root) {
Tree x, y;
x = root;
do {
x.mark = true;
if (x.left == null && x.right == null) {
y = x.parent;
} else {
y = x.left;
x.left = x.right;
x.right = x.parent;
x.parent = y;
}
x = y;
} while (x != null);
}

dafny.description:
Consider the following pseudocode algorithm, which is naive implementation of matrix
multiplication. For simplicity we assume that the matrices are square.
int[][] matrixMultiply(int[][] A, int[][] B) {
int n = A.length;
// initialise C
int[][] C = new int[n][n];
for (int i = 0; i < n; i++) {
for (int k = 0; k < n; k++) {
for (int j = 0; j < n; j++) {
C[i][j] += A[i][k] * B[k][j];
}
}
}
return C;
}

dafny.solution:
type matrix = array2<int>

predicate validMatrix(m: matrix) 
{
	m != null && m.Length0 > 0 && m.Length0 == m.Length1
}

predicate validMultiplication(a: matrix, b: matrix, c: matrix)
	requires validMatrix(a) && validMatrix(b) && validMatrix(c)
	requires a.Length0 == b.Length0 == c.Length0
{
	forall i,j | 0 <= i < a.Length0 && 0 <= j < a.Length0 :: c[i,j] == MatrixSum(a,b,i,j) 
}

function method MatrixSum(a: matrix, b: matrix, i: nat, j: nat) : int
	requires validMatrix(a) && validMatrix(b)
	requires a.Length0 == b.Length0 
	requires i < a.Length0 && j < b.Length0
{
	sum(a,b,i,j,a.Length0)
}

function method sum(a: matrix, b: matrix, i: int, j: int, k: int) : int
	requires validMatrix(a) && validMatrix(b)
	requires a.Length0 == b.Length0 
	requires 0 <= i < a.Length0 && 0 <= j < b.Length0
	requires 0 <= k <= a.Length0
{
	if k == 0 then 0 else a[i,k-1] * b[k-1,j] + sum(a,b,i,j,k - 1)
}

method MatrixMultiplication(a: matrix, b: matrix) returns (c: matrix) 
	requires validMatrix(a) && validMatrix(b)
	requires a.Length0 == b.Length0
	ensures validMatrix(c)
	ensures a.Length0 == b.Length0 == c.Length0
	ensures validMultiplication(a,b,c)
{
	var n := a.Length0;

	c := new int[n,n];

	forall i,j | 0 <= i < n && 0 <= j < n 
	{	
		c[i,j] := 0; 
