// https://formal.iti.kit.edu/ulbrich/verifythis2017


class BufImpl {
  int h;
  seq<int> xs;
  int xs_len;
  seq<int> ys;

	resource state() = Perm(h, write) ** Perm(xs, write) 
		** Perm(xs_len, write) ** Perm(ys, write) ** Perm(xs_spec, write);

	requires state();
	int h_spec() = unfolding state() in h;

